function validate([s, words]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's needs 1 to 1000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's uses only lowercase letters.';
  if (!Array.isArray(words) || words.length < 1 || words.length > 100) return 'words needs 1 to 100 strings.';
  for (const w of words) {
    if (typeof w !== 'string' || w.length < 1 || w.length > 20) return 'Each word has 1 to 20 characters.';
    if (!/^[a-z]+$/.test(w)) return 'Words use only lowercase letters.';
  }
  return null;
}

