function generate(rand, size) {
  const letters = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : 'ab';
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 5);
  const maxLen = size === 'large' ? 20 : 3;
  const word = () => {
    const len = 1 + Math.floor(rand() * maxLen);
    let w = '';
    for (let i = 0; i < len; i++) w += letters[Math.floor(rand() * letters.length)];
    return w;
  };
  const words = Array.from({ length: n }, word);
  // Build s from a prefix of words so that true answers are common, then sometimes spoil it.
  let k = 1 + Math.floor(rand() * n);
  let s = words.slice(0, k).join('');
  while (s.length > 1000) { k--; s = words.slice(0, k).join(''); }
  const mode = rand();
  if (mode < 0.2 && s.length > 1) s = s.slice(0, s.length - 1);
  else if (mode < 0.4) {
    const at = Math.floor(rand() * s.length);
    const other = letters[Math.floor(rand() * letters.length)];
    s = s.slice(0, at) + other + s.slice(at + 1);
  } else if (mode < 0.5 && s.length < 1000) s += letters[Math.floor(rand() * letters.length)];
  else if (mode < 0.6 && size === 'small') s = word() + word();
  return [s, words];
}
